"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["42129"],{2e3(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fase_que_coleta_inscricao_sem_janela","status":422,"titulo":"A fase que coleta inscri\xe7\xe3o precisa de in\xedcio e fim definidos para que o Edital declare o per\xedodo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fase_que_coleta_inscricao_sem_janela","requisitos":["UNI-REQ-0106"],"oQueAconteceu":["O cronograma tem uma fase que coleta inscri\xe7\xe3o, e ela est\xe1 sem in\xedcio, sem fim, ou\\nsem os dois. \xc9 desse per\xedodo que o Edital declara o prazo de inscri\xe7\xe3o, e um Edital\\nque admite inscri\xe7\xe3o sem dizer at\xe9 quando n\xe3o se sustenta.","A regra vale **mesmo quando a origem da data \xe9 `NA_EXECUCAO`** \u2014 a unidade\\nrespons\xe1vel pela fase define a data na execu\xe7\xe3o. Nas demais fases com essa\\norigem, a data pode ficar em aberto: ela n\xe3o \xe9 fixada no edital, e \xe9 leg\xedtimo\\npublicar um cronograma cujas fases ainda n\xe3o t\xeam data. A fase que coleta\\ninscri\xe7\xe3o \xe9 a exce\xe7\xe3o, junto da que coleta solicita\xe7\xe3o de isen\xe7\xe3o \u2014 s\xe3o as que\\nabrem prazo para o candidato agir."],"comoResolver":["Informe in\xedcio e fim do per\xedodo dessa fase no cronograma, e publique.","O prazo \xe9 declarado com **data e hora completas, at\xe9 o segundo**. Isso n\xe3o \xe9\\npreciosismo: o \xfaltimo instante de um dia \xe9 `23:59:59`, e uma fronteira em minuto\\nencurta o prazo em 59 segundos. Em prazo contado em dias corridos, o candidato\\nque enviar no \xfaltimo minuto do \xfaltimo dia fica de fora.","O preflight de conformidade mostra esta pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_fase_que_coleta_inscricao_sem_janela`."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);